        "title": "Micron announced its exit from the Crucial consumer business.",
        "summary": "On 3 December 2025, Micron announced that it would exit its Crucial consumer business, with consumer-channel shipments continuing through February 2026. The company linked the decision to rising AI demand and its intention to support larger strategic customers. This illustrates suppliers’ increasing focus on AI and enterprise markets.",
        "url": "https://www.reuters.com/business/micron-exit-crucial-consumer-memory-business-2025-12-03/"
